files.content:
:host {
  display: inline-flex;
  max-width: 80%;
  box-sizing: border-box;
  -webkit-user-select: text;
  user-select: text;
}

.message-bubble {
  min-width: 0;
  padding-block: var(--dimension-space-100);
  padding-inline: calc(var(--dimension-space-100) + var(--dimension-space-025));
  border-radius: var(--dimension-radius-100);
  background: var(--color-chrome-background-secondary);
  color: var(--color-foreground-secondary);
  font-family: var(--typography-font-family-ui);
  font-size: var(--typography-fontsize-md);
  line-height: var(--typography-lineheight-md);
  font-weight: var(--typography-weight-regular);
  letter-spacing: var(--typography-letterspacing-negative-half);
  box-sizing: border-box;
  overflow-wrap: anywhere;
}

:host(.message-bubble--user) .message-bubble {
  background: var(--color-chrome-background-primary);
  color: var(--color-foreground-primary);
}

@media (max-width: 767px) {
  .message-bubble {
    background: var(--color-background-secondary);
  }

  :host(.message-bubble--user) .message-bubble {
    background: var(--color-background-faint-neutral);
  }
}

import { Component, h, Host, Prop } from '@stencil/core';

export type MessageBubbleVariant = 'user' | 'received';

@Component({
  tag: 'ds-message-bubble',
  styleUrl: 'MessageBubble.css',
  scoped: true,
})
export class MessageBubble {
  @Prop() variant: MessageBubbleVariant = 'received';

  render() {
    return (
      <Host class={`message-bubble--${this.variant}`}>
        <div class="message-bubble">
          <slot />
        </div>
      </Host>
    );
  }
}
